      "type": "toggle",
      "label": "View",
      "options": [
        "Smooth path",
        "Sampled points"
      ],
      "default": "Smooth path",
      "teaches": "The continuous arc and a table of discrete distance–height samples describe the same motion; the curve is the limit of the sampled data."
    }
  ],
  "demo_steps": [
    {
      "title": "The flight path",
      "narration": "The ball leaves the hitter at the origin and follows a downward-opening parabola, peaking a little above 150 ft near 290 ft before landing past 560 ft.",
      "state": {
        "ballDistance": 200,
        "wallDistance": 400,
        "viewMode": "Smooth path"
      }
    },
    {
      "title": "Read a height at a distance",
      "narration": "Drag the marker along the curve: the dashed drop line to the axis and the readout show the ball's height at that exact distance from home plate.",
      "state": {
        "ballDistance": 290,
        "wallDistance": 400,
        "viewMode": "Smooth path"
      }
    },
    {
      "title": "Does it clear the wall?",
      "narration": "At the 400 ft wall the ball is still well above 100 ft — far over the barrier's top, so this is a home run.",
      "state": {
        "ballDistance": 400,
        "wallDistance": 400,
        "viewMode": "Smooth path"
      }
    },
    {
      "title": "Push the wall back",
      "narration": "Move the wall out toward 550 ft and the descending branch drops below its top: the identical hit now fails to clear.",
      "state": {
        "ballDistance": 550,
        "wallDistance": 550,
        "viewMode": "Smooth path"
      }
    },
    {
      "title": "Curve as data",
      "narration": "Switch to sampled points: the same arc appears as a set of (distance, height) pairs, linking the graph to a table of values.",
      "state": {
        "ballDistance": 290,
        "wallDistance": 400,
        "viewMode": "Sampled points"
      }
    }
  ],
  "keyInsight": "Clearing the outfield wall is not about how far the ball travels — it is about the ball's height at the wall's distance, one vertical comparison on the parabola.",
  "reconstructionNotes": "Wide landscape plot on white with black axes drawn as arrows. X-axis 'Distance (ft)' 0–600, labeled every 100; Y-axis 'Height (ft)' 0–320, labeled at 100/200/300. Light gray dotted gridlines. The trajectory is a thick teal (#1a7f9c) parabola from (0,0) through a vertex near (290,155) to about (565,0), with 4–6 small teal arrowheads along it pointing in the direction of flight. An open teal circle marks the current distance, with a thin gray dashed line dropping to the x-axis and a small readout of distance and height nearby. A short thick red rectangle sits on the axis at the wall distance (about 10 ft wide, ~15 ft tall in data units) with the label 'Outfield wall' above it in black. Black leader arrows carry the labels 'Position of hitter' (to the origin) and 'Trajectory of ball' (to the marker). In sampled-points mode the smooth curve is replaced by ~15 evenly spaced teal filled dots at the same heights, with a compact two-column list of distance/height values in a corner. Highlight the comparison at the wall with a green 'CLEARS' or orange 'HITS WALL' tag."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Distance from hitter (ft): <output id="ballDistanceVal">200</output><input id="ballDistanceInput" type="range" min="0" max="570" step="5" value="200" oninput="document.getElementById('ballDistanceVal').value=this.value;update_ballDistance(+this.value)"></label>
<label>Outfield wall distance (ft): <output id="wallDistanceVal">400</output><input id="wallDistanceInput" type="range" min="100" max="600" step="10" value="400" oninput="document.getElementById('wallDistanceVal').value=this.value;update_wallDistance(+this.value)"></label>
<label><input id="viewModeInput" type="checkbox" onchange="toggle_viewMode(this.checked)"> Sampled points view</label>
<span id="stepTitle" style="font-weight:600;font-size:12px;margin-top:4px"></span>
<p id="demoNarration" style="margin:0;font-size:11px;line-height:1.45;max-width:260px;color:#333"></p>
<span style="display:flex;gap:6px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px"></span><button onclick="nextStep()">▶</button></span>
<span style="font-size:10px;color:#666;line-height:1.4;max-width:260px">Tip: drag the open circle on the curve. Hover the curve, marker or red wall for details; click for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Model ─────────────────────────────────────────────────────────────── */
var TEAL = '#1a7f9c', RED = '#e03127', GREEN = '#12864a', ORANGE = '#d97a15';
var VX = 285, VY = 155, XEND = 570, WALLH = 25;
function ballH(x) { return VY - (VY / (VX * VX)) * (x - VX) * (x - VX); }
var st = { d: 200, wall: 400, sampled: false };

var curvePts = [];
for (var _x = 0; _x <= XEND; _x += 3) curvePts.push({ x: _x, y: ballH(_x) });
curvePts.push({ x: XEND, y: 0 });
var samplePts = [];
for (var _s = 0; _s <= 560; _s += 40) samplePts.push({ x: _s, y: Math.max(0, ballH(_s)) });

/* ── Canvas ────────────────────────────────────────────────────────────── */
var cv = document.createElement('canvas');
cv.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(cv);

function kScale(c) {
  var a = c.chartArea; if (!a) return 1;
  return Math.max(0.55, Math.min(1.5, Math.min(a.width, a.height) / 330));
}
function fnt(n, k, w) { return (w ? w + ' ' : '') + (Math.round(n * k * 10) / 10) + 'px "Segoe UI",Helvetica,Arial,sans-serif'; }
function clampN(v, a, b) { return v < a ? a : (v > b ? b : v); }

/* ── Draw helpers ──────────────────────────────────────────────────────── */
function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
}
function arrowHead(ctx, tx, ty, ang, size, color) {
  ctx.save(); ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(tx, ty);
  ctx.lineTo(tx - size * Math.cos(ang - 0.42), ty - size * Math.sin(ang - 0.42));
  ctx.lineTo(tx - size * Math.cos(ang + 0.42), ty - size * Math.sin(ang + 0.42));
  ctx.closePath(); ctx.fill(); ctx.restore();
}
function leader(ctx, x1, y1, x2, y2, color, w, head) {
  ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = w;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); ctx.restore();
  arrowHead(ctx, x2, y2, Math.atan2(y2 - y1, x2 - x1), head, color);
}
function haloText(ctx, t, x, y, font, color, align, baseline, haloW) {
  ctx.save(); ctx.font = font; ctx.textAlign = align || 'left'; ctx.textBaseline = baseline || 'alphabetic';
  ctx.lineJoin = 'round'; ctx.strokeStyle = '#fff'; ctx.lineWidth = haloW || 3.2;
  ctx.strokeText(t, x, y); ctx.fillStyle = color || '#000'; ctx.fillText(t, x, y); ctx.restore();
}
/* boxed multi-line label; anchor = 'left'|'right' relative to x, y is vertical centre */
function boxLines(ctx, lines, x, y, k, anchor, border, fonts, colors) {
  var pad = 5 * k, lh = 0, w = 0, i;
  for (i = 0; i < lines.length; i++) {
    ctx.font = fonts[i]; var m = ctx.measureText(lines[i]).width;
    if (m > w) w = m; lh += parseFloat(fonts[i]) * 1.35;
  }
  var bw = w + 2 * pad, bh = lh + 2 * pad * 0.8;
  var bx = anchor === 'right' ? x - bw : x, by = y - bh / 2;
  ctx.save();
  ctx.fillStyle = 'rgba(255,255,255,0.93)'; ctx.strokeStyle = border; ctx.lineWidth = 1.2;
  roundRect(ctx, bx, by, bw, bh, 4 * k); ctx.fill(); ctx.stroke();
  var cy = by + pad * 0.8;
  for (i = 0; i < lines.length; i++) {
    ctx.font = fonts[i]; ctx.fillStyle = colors[i]; ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText(lines[i], bx + pad, cy); cy += parseFloat(fonts[i]) * 1.35;
  }
  ctx.restore();
  return { x: bx, y: by, w: bw, h: bh };
}

/* ── Dotted gridlines ──────────────────────────────────────────────────── */
var gridPlug = {
  id: 'gridPlug',
  beforeDatasetsDraw: function (c) {
    var a = c.chartArea, X = c.scales.x, Y = c.scales.y, ctx = c.ctx, v, p;
    ctx.save(); ctx.setLineDash([1, 3]); ctx.lineWidth = 1; ctx.strokeStyle = '#b6b6b6';
    for (v = 100; v <= 600; v += 100) { p = X.getPixelForValue(v); ctx.beginPath(); ctx.moveTo(p, a.bottom); ctx.lineTo(p, a.top); ctx.stroke(); }
    for (v = 50; v <= 300; v += 50) { p = Y.getPixelForValue(v); ctx.beginPath(); ctx.moveTo(a.left, p); ctx.lineTo(a.right, p); ctx.stroke(); }
    ctx.restore();
