/* ── Model ─────────────────────────────────────────────────────────────── */
var TEAL = '#1a7f9c', RED = '#e03127', GREEN = '#12864a', ORANGE = '#d97a15';
var VX = 285, VY = 155, XEND = 570, WALLH = 25;
function ballH(x) { return VY - (VY / (VX * VX)) * (x - VX) * (x - VX); }
